// ---- DBG522b: trace callmeth self state + attribute read receiver ----
patch('DBG522b', () => {
  const J = (a, b) => JOIN(a, b);
  const log = (parts) => callProc('log %s', [parts.reduce((a, b) => J(a, b))]);
  const t = (s) => txt(s);
  global.insertAtProcStart = (defId, ids) => {
    const first = chain(ids.slice());
    const old = BL()[defId].next;
    BL()[defId].next = first; BL()[first].parent = defId;
    let tail = first; while (BL()[tail].next) tail = BL()[tail].next;
    BL()[tail].next = old; if (old) BL()[old].parent = tail;
  };
  // binerr entry
  const beDef = defIdOf('binerr');
  insertAtProcStart(beDef, [log([t('BINERR op='), VAR('beop'), t(' LT='), VAR('binLT'), t(' RT='), VAR('binRT'), t(' L='), VAR('binL'), t(' R='), VAR('binR')])]);
  // callmeth entry + after-assign self state
  const cmDef = defIdOf('callmeth %s %s %s %s');
  const cmBody = BL()[cmDef].next;
  // find the assign('self', inst, 'O') call inside callmeth: second procedures_call
  let c = cmBody, assigns = [];
  while (c) { const q = BL()[c]; if (q.opcode === 'procedures_call' && q.mutation && String(q.mutation.proccode) === 'assign %s %s %s') assigns.push(c); c = q.next; }
  if (assigns.length < 1) throw new Error('[DBG522b] callmeth assign not found');
  const insertAfterStmt2 = (targetId, ids) => {
    const first = chain(ids.slice());
    const nx = BL()[targetId].next;
    BL()[targetId].next = first; BL()[first].parent = targetId;
    let tail = first; while (BL()[tail].next) tail = BL()[tail].next;
    BL()[tail].next = nx; if (nx) BL()[nx].parent = tail;
    return first;
  };
  insertAfterStmt2(assigns[0], [
    callProc('lookup %s', [txt('self')]),
    log([t('CM inst='), argOf('inst'), t(' lookup(self) found='), VAR('found'), t(' val='), item('Values', VAR('found'))])
  ]);
  // attribute read: after eval(lo,lo) in the 3-token branch
  const evDef = defIdOf('eval %s %s');
  // find the attribute read IF: contains set iid = ev  (data_setvariableto iid with VALUE var ev)
  const attrIfs = find(evDef, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'iid'
    && b.inputs.VALUE && typeof b.inputs.VALUE[1] === 'string' && BL()[b.inputs.VALUE[1]]
    && BL()[b.inputs.VALUE[1]].opcode === 'data_variable' && BL()[b.inputs.VALUE[1]].fields.VARIABLE[0] === 'ev');
  console.log('[DBG522b] iid=ev sites in eval: ' + attrIfs.length);
  for (const id of attrIfs) {
    insertAfterStmt2(id, [
      log([t('ATTR iid='), VAR('iid'), t(' recvT='), VAR('evtype')])
    ]);
  }
  console.log('[DBG522b] ok');
});

