const proj=JSON.parse(require('fs').readFileSync('_work/v41/project.json','utf8'));
const BB=proj.targets.find(t=>t.name==='Interpreter').blocks;
const proto=Object.values(BB).find(b=>b.opcode==='procedures_prototype'&&b.mutation&&String(b.mutation.proccode)==='eval %s %s');
