  for(const v of Object.values(BB[id].inputs||{})) if(v&&typeof v[1]==='string') stack.push(v[1]);
  if(BB[id].next) stack.push(BB[id].next); }
const sets=[...seen].filter(id=>BB[id].opcode==='data_setvariableto'&&BB[id].fields.VARIABLE[0]==='iid');
