  const v=BB[s].inputs.VALUE;
  let desc='?';
  if(Array.isArray(v)&&v[0]===12) desc='VAR '+v[1];
  else if(Array.isArray(v)&&typeof v[1]==='string'&&BB[v[1]]) desc=BB[v[1]].opcode;
  else if(Array.isArray(v)) desc=JSON.stringify(v).slice(0,80);
  console.log(' ', s, '->', desc);
}
"

