// ---- P525: round(x, n) 用位数组判定对齐 CPython 的 correct rounding ----
//
// 现状：n>0 走 `mrt = v*10^n; roundpy(mrt); ev = 结果/10^n`。但 IEEE 乘法自身
// 会把真值略小的数**舍到恰好 0.5**：JS 里 2.675*100 === 267.5（2.675 的双精度
// 真值是 2.67499999999999982…，乘积 267.499…982 就近舍入成 267.5）→ roundpy
// 半偶进位 → 2.68，而 CPython 用双精度的**精确十进制展开**判定 → 2.67。
// 修法：新过程 rounddigits(v, nd) —— I = floor(|v|·10^(nd+8))，看末 8 位：
//   >5e7 进位、<5e7 舍去、==5e7 半偶（base 奇数才进位）；结果 = ±base/10^nd。
// 10^(nd+8) ≤ 1e15（nd ≤ 7）时精确；更大 n 回落旧缩放路径（tie 在大数下罕见）。
// n<0 分支现状正确（1200.0），不动。
patch('P525 round ndigits digit-decision', () => {
  // ---- 新过程 rounddigits %s %s (v, nd) -> ev/evtype ----
  const rd = newProc('rounddigits %s %s', ['v', 'nd']);
  const powCalc = [
    setV('p25a', num(1)),
    setV('p25k', ADD(argOf('nd'), num(8))),
    REPEATU(GT(VAR('p25k'), num(0)), [setV('p25a', MUL(VAR('p25a'), num(10))), chgV('p25k', num(-1))])
  ];
  attachBody(rd.defId, [
    setV('p25s', argOf('v')),
    IF(LT(VAR('p25s'), num(0)), [setV('p25s', SUB(num(0), VAR('p25s')))]),
    ...powCalc,
    // p25a = 10^(nd+8)
    setV('p25I', FLOOR(MUL(VAR('p25s'), VAR('p25a')))),
    setV('p25b', FLOOR(DIV(VAR('p25I'), num(100000000)))),
    setV('p25r', MOD(VAR('p25I'), num(100000000))),
    IF(GT(VAR('p25r'), num(50000000)), [setV('p25b', ADD(VAR('p25b'), num(1)))]),
    IFELSE(EQ(VAR('p25r'), num(50000000)), [
      IF(EQ(MOD(VAR('p25b'), num(2)), num(1)), [setV('p25b', ADD(VAR('p25b'), num(1)))])
    ], []),
    // result = ±base / 10^nd
    setV('p25c', num(1)),
    setV('p25k', argOf('nd')),
    REPEATU(GT(VAR('p25k'), num(0)), [setV('p25c', MUL(VAR('p25c'), num(10))), chgV('p25k', num(-1))]),
    setV('ev', DIV(VAR('p25b'), VAR('p25c'))),
    IF(LT(argOf('v'), num(0)), [setV('ev', SUB(num(0), VAR('ev')))]),
    setV('evtype', txt('N'))
  ]);
  // ---- 替换 builtin2b round 分支 n>0 一侧的缩放三连 ----
  const b2 = inDef('builtin2b %s %s %s %s %s');
  // n>0 侧的特征：set mrt = a1v * qpow（operator_multiply），后随 roundpy 调用与 ev=ev/qpow
  const mrtSets = find(b2, (b) => b.opcode === 'data_setvariableto' && b.fields.VARIABLE[0] === 'mrt');
  let replaced = 0;
  for (const id of mrtSets) {
    const val = BL()[id].inputs.VALUE[1];
    if (typeof val !== 'string' || !BL()[val] || BL()[val].opcode !== 'operator_multiply') continue;
    // 找到这段链的尾部（ev = ev / qpow 的 set）
    let tail = null, cur = BL()[id].next, hops = 0;
    while (cur && hops++ < 6) {
      const q = BL()[cur];
      if (q.opcode === 'data_setvariableto' && q.fields.VARIABLE[0] === 'ev'
          && typeof q.inputs.VALUE[1] === 'string' && BL()[q.inputs.VALUE[1]]
          && BL()[q.inputs.VALUE[1]].opcode === 'operator_divide') { tail = cur; break; }
      cur = q.next;
    }
    if (!tail) continue;
    const after = BL()[tail].next;
    // 断链并把 [id..tail] 摘下
    BL()[id].next = null;
    const call = callProc('rounddigits %s %s', [argOf('a1v'), VAR('ev')]);
    let pred = null;
    for (const pid of allIds()) if (BL()[pid] && BL()[pid].next === id) { pred = pid; break; }
    if (!pred) throw new Error('[P525] predecessor of mrt set not found');
    BL()[pred].next = call;
    BL()[call].parent = pred;
    BL()[call].next = after;
    if (after) BL()[after].parent = call;
    replaced++;
  }
  if (replaced !== 1) throw new Error('[P525] round n>0 branch replaced=' + replaced);
  console.log('[P525] rounddigits installed; builtin2b n>0 path rewired');
});

