const proj=JSON.parse(require('fs').readFileSync('_work/v41/project.json','utf8'));
const BB=proj.targets.find(t=>t.name==='Interpreter').blocks;
const procOf={};
for(const [id,b] of Object.entries(BB)){
  if(b.opcode==='procedures_definition'&&b.inputs&&b.inputs.custom_block){
    const p=BB[b.inputs.custom_block[1]];
    procOf[id]=p&&p.mutation?String(p.mutation.proccode):'?';
  }
}
// which procs contain operator_round or roundpy calls
const ownerOf=(startId)=>{ // walk up parents (saved project has parent? use reverse reach from each def — expensive but ok)
  return null; };
const counts={};
for(const [id,b] of Object.entries(BB)){
  let hit=null;
  if(b.opcode==='operator_round') hit='op_round';
  else if(b.opcode==='procedures_call'&&b.mutation&&String(b.mutation.proccode).startsWith('roundpy')) hit='roundpy';
  else if(b.opcode==='procedures_call'&&b.mutation&&String(b.mutation.proccode).startsWith('rounddigits')) hit='rounddigits';
  if(hit){
    // find owning proc by reach scan
    if(!counts[hit]) counts[hit]={};
    counts[hit][id]=true;
  }
}
// map each hit to its proc via reach from every def (cache)
const owner=new Map();
for(const [defId,pc] of Object.entries(procOf)){
  const seen=new Set(); const stack=[BB[defId].next];
  while(stack.length){ const x=stack.pop(); if(!x||seen.has(x)||!BB[x])continue; seen.add(x);
    for(const v of Object.values(BB[x].inputs||{})) if(v&&typeof v[1]==='string') stack.push(v[1]);
    if(BB[x].next) stack.push(BB[x].next); }
  for(const x of seen) if(!owner.has(x)) owner.set(x,pc);
}
for(const kind of ['op_round','roundpy','rounddigits']){
  const byProc={};
  for(const id of Object.keys(counts[kind]||{})){ const p=owner.get(id)||'?'; byProc[p]=(byProc[p]||0)+1; }
  console.log(kind, JSON.stringify(byProc));
}
