const proj=JSON.parse(require('fs').readFileSync('_work/v41/project.json','utf8'));
const BB=proj.targets.find(t=>t.name==='Interpreter').blocks;
// who calls the two fail sites? walk up: find the if conditions again and their position within eval
// instead: instrument by REPLACING the fail blocks' message with a marker list append BEFORE them via parent if rewrite
// simpler: find the two fail sites and their ancestor IFs; log the IF conditions
const fails=[];
for(const [id,b] of Object.entries(BB)){
  if(b.opcode==='procedures_call'&&b.mutation&&b.mutation.proccode==='fail %s'&&JSON.stringify(b.inputs).includes('parentheses')) fails.push(id);
}
for(const f of fails){
  // find enclosing if via parent
  const p=BB[f].parent;
  console.log('fail', f, 'parent', p, BB[p]&&BB[p].opcode);
  if(p&&BB[p].inputs&&BB[p].inputs.CONDITION){
    const vars=new Set(); const st=[BB[p].inputs.CONDITION[1]];
    while(st.length){ const x=st.pop(); if(!x||!BB[x])continue; const b3=BB[x];
      if(b3.fields&&b3.fields.VARIABLE) vars.add(b3.fields.VARIABLE[0]);
      for(const v of Object.values(b3.inputs||{})) if(Array.isArray(v)&&v[0]===12) vars.add(v[1]);
      for(const v of Object.values(b3.inputs||{})) if(v&&typeof v[1]==='string') st.push(v[1]); }
    console.log('  cond vars:', [...vars].join(','));
  }
  // grandparent chain via parent
  let g=BB[p]?BB[p].parent:null, d=0;
  while(g&&d<6){ console.log('  up'+d+':', BB[g]?BB[g].opcode:'?'); g=BB[g]?BB[g].parent:null; d++; }
}
"

