// ---- P530: float('-0.0') 保留负零符号 ----
//
// CPython float('-0.0') → -0.0（打印 '-0.0'）；本解释器把文本转成 JS 数值后
// 符号丢失，打印 '0.0'。修法：float() 分支在 mkfloat 之前——若实参是 S 记号、
// 首字符为 '-' 且数值为 0，直接把 ev 置为 '-0.0'（mkfloat 对已带 .0 的文本无操作）。
// 覆盖 cov1 float conversions 与补充套件 negative zero float 的 float('-0.0') 项。
patch('P530 float keeps negative zero', () => {
  const cf = inDef('callfn %s %s %s');
  const fBranch = find(cf, (b) => b.opcode === 'control_if' && b.inputs.CONDITION && typeof b.inputs.CONDITION[1] === 'string'
    && [...reach(b.inputs.CONDITION[1])].some((x) => {
      const q = BL()[x];
      return q && q.opcode === 'operator_equals' && q.inputs.OPERAND2 && Array.isArray(q.inputs.OPERAND2[1]) && q.inputs.OPERAND2[1][1] === 'float';
    }));
  if (fBranch.length !== 1) throw new Error('[P530] float() branch = ' + fBranch.length);
  const fFirst = BL()[fBranch[0]].inputs.SUBSTACK[1];
  // 找分支里已有的 mkfloat 调用（P122 插的），插到它前面
  const mk = find(reach(fFirst), (b) => b.opcode === 'procedures_call' && b.mutation && String(b.mutation.proccode) === 'mkfloat %s'
    && [...reach(b)].length >= 0);
  let mkSite = null;
  for (const id of mk) {
    const all = [...reach(id)].map((x) => JSON.stringify(BL()[x])).join('');
    if (all.includes('"float"')) { mkSite = id; break; }
  }
  if (!mkSite) throw new Error('[P530] mkfloat-in-float-branch not found');
  const negz = IF(AND(EQ(item('Kind', ADD(argOf('lo'), num(2))), txt('S')), AND(EQ(letterOf(num(1), item('Tok', ADD(argOf('lo'), num(2)))), txt('-')), EQ(VAR('ev'), num(0)))), [
    setV('ev', txt('-0.0'))
  ]);
  insertBeforeStmt(mkSite, [negz]);
  console.log('[P530] float("-0.0") preserves the sign');
});
EOF
